import { Zap, Code2, Shield, Brain, Lock, Activity, Check, LucideIcon } from 'lucide-react';

interface ProjectCardProps {
  title: string;
  description: string;
  technologies: string[];
  icon: string;
  isVisible: boolean;
  delay: number;
  metrics?: string;
}

const iconMap: Record<string, LucideIcon> = { Zap, Code2, Shield, Brain, Lock, Activity };

export default function ProjectCard({ title, description, technologies, icon, isVisible, delay, metrics }: ProjectCardProps) {
  const Icon = iconMap[icon] || Zap;

  return (
    <article
      className={`card opacity-0 ${isVisible ? 'animate-fade-in' : ''}`}
      style={{ animationDelay: `${delay}s` }}
    >
      <div className="flex items-center gap-3 mb-4">
        <div className="w-9 h-9 rounded-lg bg-accent-subtle border border-accent/20 flex items-center justify-center shrink-0">
          <Icon size={18} className="text-accent" />
        </div>
        <h3 className="text-base font-semibold text-fg leading-tight">{title}</h3>
      </div>

      <p className="text-fg-muted text-sm leading-relaxed mb-4">{description}</p>

      {metrics && (
        <div className="mb-4 flex items-center gap-2 px-3 py-2 rounded-md bg-accent-subtle border border-accent/20">
          <Check size={14} className="text-accent" />
          <span className="text-accent text-xs font-medium">{metrics}</span>
        </div>
      )}

      <div className="flex gap-1.5 flex-wrap">
        {technologies.map((tech) => (
          <span key={tech} className="px-2.5 py-1 rounded-md bg-bg-muted text-fg-muted text-xs">{tech}</span>
        ))}
      </div>
    </article>
  );
}
